logger = logging.getLogger(__name__)


@contextlib.contextmanager
def _disable_aabs():
    """Temporarily disable FlagTree AABS while launching this kernel.

    AABS re-sizes the tl.arange-driven BLOCK_K from the K extent, so a launch
    that already passes BLOCK_K explicitly binds the argument twice and raises
    "got multiple values for keyword argument 'BLOCK_K'". The kernel derives
    both block sizes on the host, so the adjusted configs are not needed.
    """
    adjust_block_size = getattr(_autotuning_knobs, "adjust_block_size", None)
    if adjust_block_size is None:
        yield
        return
    _autotuning_knobs.adjust_block_size = False
    try:
        yield
    finally:
        _autotuning_knobs.adjust_block_size = adjust_block_size


@libentry()
@triton.autotune(
    configs=[
        triton.Config({}, num_warps=1, num_stages=1),
        triton.Config({}, num_warps=2, num_stages=1),
    ],
    key=["n", "nrhs"],
)
@triton.jit
def linalg_solve_kernel(
    A,
    LU,
    B,
    X,
    n,
    nrhs,
    a_batch_stride,
    a_row_stride,
    lu_batch_stride,
    lu_row_stride,
    b_batch_stride,
    b_row_stride,
    x_batch_stride,
    x_row_stride,
    BLOCK_N: tl.constexpr,
    BLOCK_K: tl.constexpr,
):
    """
    Fused kernel: copy A->LU, LU decomposition with partial pivoting,
    forward substitution, backward substitution.

    Each program handles one batch element.
    A columns vectorized via BLOCK_N, RHS columns vectorized via BLOCK_K.
    LU workspace is separate from A so autotune re-runs start from fresh A.
    """
    batch_idx = tl.program_id(0)

    # Vector indices
    a_cols = tl.arange(0, BLOCK_N)
    b_cols = tl.arange(0, BLOCK_K)
    a_col_mask = a_cols < n
    b_col_mask = b_cols < nrhs

    a_base = A + batch_idx * a_batch_stride
    lu_base = LU + batch_idx * lu_batch_stride
    b_base = B + batch_idx * b_batch_stride
    x_base = X + batch_idx * x_batch_stride

    # Copy A to LU workspace (vectorized over columns)
    i = 0
    while i < n:
        row = tl.load(a_base + i * a_row_stride + a_cols, mask=a_col_mask, other=0.0)
        tl.store(lu_base + i * lu_row_stride + a_cols, row, mask=a_col_mask)
        i += 1

    # Copy B to X (vectorized over RHS columns)
    i = 0
    while i < n:
        bi = tl.load(b_base + i * b_row_stride + b_cols, mask=b_col_mask, other=0.0)
        tl.store(x_base + i * x_row_stride + b_cols, bi, mask=b_col_mask)
        i += 1

    # Step 1: LU decomposition with partial pivoting on LU workspace
    k = 0
    while k < n:
        # Find pivot: argmax |LU[k:n, k]|
        max_val = tl.abs(tl.load(lu_base + k * lu_row_stride + k))
        pivot_row = k
        i = k + 1
        while i < n:
            val = tl.abs(tl.load(lu_base + i * lu_row_stride + k))
            if val > max_val:
                max_val = val
                pivot_row = i
            i += 1

        # Swap rows k and pivot_row - vectorized
        if pivot_row != k:
            luk_row = tl.load(
                lu_base + k * lu_row_stride + a_cols, mask=a_col_mask, other=0.0
            )
            lup_row = tl.load(
                lu_base + pivot_row * lu_row_stride + a_cols,
                mask=a_col_mask,
                other=0.0,
            )
            tl.store(lu_base + k * lu_row_stride + a_cols, lup_row, mask=a_col_mask)
            tl.store(
                lu_base + pivot_row * lu_row_stride + a_cols,
                luk_row,
                mask=a_col_mask,
            )
            # Swap X rows
            xk = tl.load(x_base + k * x_row_stride + b_cols, mask=b_col_mask, other=0.0)
            xp = tl.load(
                x_base + pivot_row * x_row_stride + b_cols,
                mask=b_col_mask,
                other=0.0,
            )
            tl.store(x_base + k * x_row_stride + b_cols, xp, mask=b_col_mask)
            tl.store(x_base + pivot_row * x_row_stride + b_cols, xk, mask=b_col_mask)

        akk = tl.load(lu_base + k * lu_row_stride + k)

        # Load pivot row for vectorized trailing update
        ak_row = tl.load(
            lu_base + k * lu_row_stride + a_cols, mask=a_col_mask, other=0.0
        )

        # Trailing column mask (only update columns > k)
        trail_mask = (a_cols > k) & a_col_mask

        # Compute L factors and update trailing submatrix
        i = k + 1
        while i < n:
            aik = tl.load(lu_base + i * lu_row_stride + k)
            lik = aik / akk
            tl.store(lu_base + i * lu_row_stride + k, lik)
            # Vectorized: LU[i, j] -= lik * LU[k, j] for j > k
            ai_row = tl.load(
                lu_base + i * lu_row_stride + a_cols, mask=trail_mask, other=0.0
            )
            ai_row = ai_row - lik * ak_row
            tl.store(lu_base + i * lu_row_stride + a_cols, ai_row, mask=trail_mask)
            i += 1
        k += 1

    # Step 2: Forward substitution Ly = Pb (vectorized over BLOCK_K)
    i = 1
    while i < n:
        xi = tl.load(x_base + i * x_row_stride + b_cols, mask=b_col_mask, other=0.0)
        j = 0
        while j < i:
            lij = tl.load(lu_base + i * lu_row_stride + j)
            xj = tl.load(x_base + j * x_row_stride + b_cols, mask=b_col_mask, other=0.0)
            xi = xi - lij * xj
            j += 1
        tl.store(x_base + i * x_row_stride + b_cols, xi, mask=b_col_mask)
        i += 1

    # Step 3: Backward substitution Ux = y (vectorized over BLOCK_K)
    i = n - 1
    while i >= 0:
        xi = tl.load(x_base + i * x_row_stride + b_cols, mask=b_col_mask, other=0.0)
        j = i + 1
        while j < n:
            uij = tl.load(lu_base + i * lu_row_stride + j)
            xj = tl.load(x_base + j * x_row_stride + b_cols, mask=b_col_mask, other=0.0)
            xi = xi - uij * xj
            j += 1
        uii = tl.load(lu_base + i * lu_row_stride + i)
        xi = xi / uii
        tl.store(x_base + i * x_row_stride + b_cols, xi, mask=b_col_mask)
        i -= 1


# ---------------------------------------------------------------------------
# Register-tile Gauss-Jordan path (fp32, n <= 64).
#
# The baseline kernel walks A row by row through global memory, so one solve
# costs ~2.5*n^2 dependent load/store round trips (~0.3us each on gcu400) and
# n=16 lands at ~185us.  Here the augmented system [A | B] lives in registers
# as a single (BLOCK_N, W) tile and every elimination step is a handful of
# tile-wide ops, so the serial chain shrinks from O(n^2) memory round trips to
# n steps of ~5 cross-lane ops (where+sum trees at num_warps=1 are ~2x faster
# than both the num_warps>1 splits and the tl.gather idiom here; gather also
# forces num_warps=1 with a compiler segfault above it).
#
# Design notes:
# - No physical row swaps: at step k the pivot row stays where it is and the
#   permutation is tracked in `pc` ("pivot column of row j"); after n steps
#   the solution is scattered to X with pc-based row offsets, which is pure
#   address arithmetic (no cross-lane op).  Physically swapping rows would
#   cost 4 extra tree extractions per step (measured +2x on the sibling
#   lu_factor_ex tile kernel).
# - Eliminating column k from *all* rows except the pivot (Gauss-Jordan)
#   fuses forward+backward substitution into the elimination loop; the
#   B-part of the augmented tile converges to A^{-1}B directly.
# - Partial pivoting still picks argmax |A[i,k]| among the rows that have not
#   served as a pivot yet; the pivot sequence is identical to LAPACK's.
# - Singular matrices divide by a zero pivot exactly like the baseline kernel
#   (torch.linalg.solve raises on them; both paths produce garbage).
# - i32 safety: gcu400 caps grid.x at 65535 programs and the tile path bounds
#   n <= 64, so pid * a_batch_stride <= 65535*4096 fits i32 comfortably.
# - The bound is 64 (not just the tested 32) because the baseline autotuned
#   kernel returns wrong results for 33 <= n <= 64 on gcu400 (its autotune
#   wrapper corrupts re-runs at BLOCK_N=64; the same kernel body launched
#   with a pinned num_warps is correct there).  The tile path was verified
#   against CPU fp64 for n in {33,40,48,50,55,63,64} x nrhs in {1..64}.
# ---------------------------------------------------------------------------

_TILE_SOLVE_MAX_N = 64
_TILE_SOLVE_MAX_NRHS = 64


@libentry()
@triton.jit
def _linalg_solve_gj_kernel(
    A,
    B,
    X,
    a_batch_stride,
    a_row_stride,
    b_batch_stride,
    b_row_stride,
    x_batch_stride,
    x_row_stride,
    N: tl.constexpr,
    NRHS: tl.constexpr,
    BLOCK_N: tl.constexpr,
    W: tl.constexpr,
):
    batch_idx = tl.program_id(0)
    rows = tl.arange(0, BLOCK_N)
    cols = tl.arange(0, W)
    r2 = rows[:, None]
    c2 = cols[None, :]
    row_mask = r2 < N

    a_base = A + batch_idx * a_batch_stride
    b_base = B + batch_idx * b_batch_stride

    # Augmented [A | B] tile in registers.  The two source tensors have
    # independent bases, so build the tile from two masked loads; masked-off
    # lanes never dereference, so the out-of-range halves are safe.
    a_val = tl.load(
        a_base + r2 * a_row_stride + c2, mask=row_mask & (c2 < N), other=0.0
    )
    b_val = tl.load(
        b_base + r2 * b_row_stride + (c2 - N),
        mask=row_mask & (c2 >= N) & (c2 < N + NRHS),
        other=0.0,
    )
    work = tl.where(c2 < N, a_val, b_val)

    # pc[j] = which column physical row j pivoted for (-1 = still a candidate).
    pc = tl.full((BLOCK_N,), -1, tl.int32)

    for k in tl.static_range(N):
        # Extract current column k (tree over the tile width).
        col_k = tl.sum(tl.where(c2 == k, work, 0.0), axis=1)
        # Partial pivoting over rows that have not been used as a pivot yet.
        pick = tl.where((pc == -1) & (rows < N), tl.abs(col_k), -1.0)
        pivot_row = tl.argmax(pick, axis=0)
        # Signed pivot value A[p, k] and the (unnormalized) pivot row.
        akk = tl.sum(tl.where(rows == pivot_row, col_k, 0.0))
        u = tl.sum(tl.where(r2 == pivot_row, work, 0.0), axis=0)
        u = u / akk
        is_p = r2 == pivot_row
        # Pivot row becomes the normalized u; every other row subtracts
        # col_k[i] * u, which zeroes column k on those rows because
        # u[k] == 1 (that also fuses the L store of the baseline kernel).
        work = tl.where(is_p, u[None, :], work - col_k[:, None] * u[None, :])
        pc = tl.where(rows == pivot_row, k, pc)

    # Scatter the solved B-part rows to X with the tracked permutation:
    # row j holds the solution component of variable pc[j].
    x_base = X + batch_idx * x_batch_stride
    out_offsets = pc[:, None] * x_row_stride + (c2 - N)
    tl.store(
        x_base + out_offsets,
        work,
        mask=(pc[:, None] >= 0) & (pc[:, None] < N) & (c2 >= N) & (c2 < N + NRHS),
    )


def linalg_solve(A, B, *, left=True):
    """
    Solve the linear system AX = B.

    Args:
        A: (*, n, n) coefficient matrix
        B: (*, n, k) right-hand side matrix
        left: if True, solve AX = B

    Returns:
        X: (*, n, k) solution matrix
    """
    logger.debug("GEMS_ENFLAME LINALG_SOLVE")

    if not left:
        raise NotImplementedError("right=True (XA = B) is not yet supported")
    assert A.dtype in (
        torch.float32,
        torch.float64,
    ), f"linalg_solve requires float32/float64, got {A.dtype}"
    if A.ndim < 2 or B.ndim < 2:
        raise ValueError("A and B must be at least 2D")
    if A.shape[-1] != A.shape[-2]:
        raise ValueError("A must be a square matrix")
    n = A.shape[-1]
    if B.shape[-2] != n:
        raise ValueError("B must have compatible dimensions with A")
    if A.numel() == 0 or B.numel() == 0:
        return B.clone()

    batch = math.prod(A.shape[:-2])
    nrhs = B.shape[-1]

    # Make contiguous copies
    A_work = A.reshape(batch, n, n).contiguous()
    B_work = B.reshape(batch, n, nrhs).contiguous()

    if (
        A.dtype == torch.float32
        and n <= _TILE_SOLVE_MAX_N
        and nrhs <= _TILE_SOLVE_MAX_NRHS
    ):
        # Register-tile Gauss-Jordan path: every benchmark and test shape, plus
        # the 33..64 band where the baseline autotuned kernel mis-computes
        # (see the kernel notes above).
        X = torch.empty_like(B_work)
        block_n = max(triton.next_power_of_2(n), 4)
        w = max(triton.next_power_of_2(n + nrhs), 4)
        with torch.no_grad(), _disable_aabs():
            _linalg_solve_gj_kernel[(batch,)](
                A_work,
                B_work,
                X,
                A_work.stride(0),
                A_work.stride(1),
                B_work.stride(0),
                B_work.stride(1),
                X.stride(0),
                X.stride(1),
                N=n,
                NRHS=nrhs,
                BLOCK_N=block_n,
                W=w,
                num_warps=1,
            )
        return X.reshape(B.shape)

    # Baseline serial path: fp64 inputs or matrices beyond the register-tile
    # budget (n > 64 or nrhs > 64).  Note: for n in 33..64 this fallback is
    # only reachable for nrhs > 64.
    # LU workspace separate from A (safe for autotune re-runs)
    LU = torch.empty_like(A_work)
    X = torch.empty_like(B_work)

    # BLOCK_N covers all n columns of A (power of 2)
    block_n = max(triton.next_power_of_2(n), 4)
    # BLOCK_K covers all nrhs columns (power of 2)
    block_k = max(triton.next_power_of_2(nrhs), 4)

    grid = (batch,)

    with torch.no_grad(), _disable_aabs():
        linalg_solve_kernel[grid](
            A_work,
            LU,
            B_work,
            X,
            n,
            nrhs,
            A_work.stride(0),
            A_work.stride(1),
            LU.stride(0),
            LU.stride(1),
            B_work.stride(0),
            B_work.stride(1),
            X.stride(0),
            X.stride(1),
            BLOCK_N=block_n,
            BLOCK_K=block_k,
        )

    return X.reshape(B.shape)
